pub(crate) fn recognized(base: &str) -> bool {
    lookup(base).is_some()
}

pub(crate) fn aes_builtin(base: &str) -> Option<Intrinsic> {
    match lookup(base)? {
        Binding::Aes(id) => Some(id),
        _ => None,
    }
}

pub(crate) fn packed_shift_builtin(base: &str) -> Option<(Intrinsic, VectorType, bool)> {
    match lookup(base)? {
        Binding::PackedShift(id, shape, immediate) => Some((id, shape, immediate)),
        _ => None,
    }
}

pub(crate) fn saturating_builtin(base: &str) -> Option<(Intrinsic, bool, bool)> {
    match lookup(base)? {
        Binding::Saturating(id, unsigned, word) => Some((id, unsigned, word)),
        _ => None,
    }
}

pub(crate) fn packed_conversion_builtin(base: &str) -> Option<Intrinsic> {
    match lookup(base)? {
        Binding::PackedConversion(id) => Some(id),
        _ => None,
    }
}

pub(crate) fn semantic_builtin(
    base: &str,
) -> Option<(Intrinsic, Option<&'static ImmediateControl>)> {
    match lookup(base)? {
        Binding::Value(id, control) => Some((id, control)),
        _ => None,
    }
}

